# Run from the repo root, after orange_leader_pics.py.
# 0. Fixes the Orange (and Johto) NPC overworld sprites, which did not show in game:
#    - ivy/cissy/danny/rudy/luana.png had no spritesheet rule, so they were converted as plain
#      tiles instead of 16x32 frames (adds the -mwidth 2 -mheight 4 rules; stale .4bpp removed)
#    - their palettes used the map-dependent "special" slot; Walker, the Johto leaders, Elm, Ivy and
#      the Orange leaders now load their palettes on demand, like follower Pokemon do
# 1. Overworld sprites for Cissy, Danny, Rudy and Luana recoloured to match their new battle pictures.
# 2. Drake (Orange League head): new battle picture (from Brock's FRLG pose: black spiky hair,
#    red sleeveless vest with orange stripes and a high collar, dark undershirt with a Poke Ball
#    pendant, fingerless gloves, baggy blue trousers, grey boots) and a 10-frame overworld sprite.
#    Adds TRAINER_PIC_ORANGE_DRAKE and OBJ_EVENT_GFX_ORANGE_DRAKE; TRAINER_CHAMPION_DRAKE uses the new pic.
import base64, re
def rd(p): return open(p, encoding='utf-8').read()
def wr(p, s): open(p, 'w', newline='\n', encoding='utf-8').write(s)
def sub1(s, old, new, p):
    assert old in s, (p, old[:60]); return s.replace(old, new, 1)
FILES = {'graphics/object_events/pics/people/cissy.png': '', 'graphics/object_events/pics/people/danny.png': '', 'graphics/object_events/pics/people/rudy.png': '', 'graphics/object_events/pics/people/luana.png': '', 'graphics/object_events/pics/people/orange_drake.png': '', 'graphics/trainers/front_pics/orange_drake_front_pic.png': ''}
for k, b in FILES.items(): open(k, 'wb').write(base64.b64decode(b))

p = 'include/constants/trainers.h'; s = rd(p)
if 'TRAINER_PIC_ORANGE_DRAKE' not in s:
    s = re.sub(r'#define TRAINER_PIC_COUNT\s+160', '#define TRAINER_PIC_ORANGE_DRAKE          160\n#define TRAINER_PIC_COUNT                 161', s); assert 'ORANGE_DRAKE' in s
    wr(p, s)
p = 'include/constants/event_objects.h'; s = rd(p)
if 'OBJ_EVENT_GFX_ORANGE_DRAKE' not in s:
    s = re.sub(r'#define NUM_OBJ_EVENT_GFX\s+173', '#define OBJ_EVENT_GFX_ORANGE_DRAKE 173\n#define NUM_OBJ_EVENT_GFX     174', s); assert 'ORANGE_DRAKE' in s
    wr(p, s)
p = 'include/graphics.h'; s = rd(p)
if 'gTrainerFrontPic_OrangeDrake' not in s:
    s = sub1(s, 'extern const u32 gTrainerPalette_Luana[];\n', 'extern const u32 gTrainerPalette_Luana[];\nextern const u32 gTrainerFrontPic_OrangeDrake[];\nextern const u32 gTrainerPalette_OrangeDrake[];\n', p); wr(p, s)
p = 'src/data/graphics/trainers.h'; s = rd(p)
if 'OrangeDrake' not in s:
    s = sub1(s, 'const u32 gTrainerPalette_Luana[] = INCBIN_U32("graphics/trainers/front_pics/luana_front_pic.gbapal.lz");\n',
        'const u32 gTrainerPalette_Luana[] = INCBIN_U32("graphics/trainers/front_pics/luana_front_pic.gbapal.lz");\n'
        'const u32 gTrainerFrontPic_OrangeDrake[] = INCBIN_U32("graphics/trainers/front_pics/orange_drake_front_pic.4bpp.lz");\n'
        'const u32 gTrainerPalette_OrangeDrake[] = INCBIN_U32("graphics/trainers/front_pics/orange_drake_front_pic.gbapal.lz");\n', p); wr(p, s)
p = 'src/data/trainer_graphics/front_pic_tables.h'; s = rd(p)
if 'ORANGE_DRAKE' not in s:
    s = sub1(s, '    {.size = 8, .y_offset = 1}, // LUANA\n', '    {.size = 8, .y_offset = 1}, // LUANA\n    {.size = 8, .y_offset = 1}, // ORANGE_DRAKE\n', p)
    s = sub1(s, '    TRAINER_SPRITE(LUANA, gTrainerFrontPic_Luana, 0x800),\n', '    TRAINER_SPRITE(LUANA, gTrainerFrontPic_Luana, 0x800),\n    TRAINER_SPRITE(ORANGE_DRAKE, gTrainerFrontPic_OrangeDrake, 0x800),\n', p)
    s = sub1(s, '    TRAINER_PAL(LUANA, gTrainerPalette_Luana)\n', '    TRAINER_PAL(LUANA, gTrainerPalette_Luana),\n    TRAINER_PAL(ORANGE_DRAKE, gTrainerPalette_OrangeDrake)\n', p)
    wr(p, s)
p = 'src/data/trainer_graphics/front_pic_anims.h'; s = rd(p)
if 'ORANGE_DRAKE' not in s:
    s, n = re.subn(r'(    \[TRAINER_PIC_LUANA\]\s*=\s*\w+,\n)', r'\1    [TRAINER_PIC_ORANGE_DRAKE]      = sAnims_LeaderBrock,\n', s); assert n == 1; wr(p, s)
for p, val in (('src/data/battle_transitions/mugshot_coords.h', '{ 0, 0}'), ('src/data/battle_transitions/mugshot_rotation_scales.h', '0x200')):
    s = rd(p)
    if 'ORANGE_DRAKE' not in s:
        s, n = re.subn(r'( \[TRAINER_PIC_LUANA\][^\n]*\n)', r'\1 [TRAINER_PIC_ORANGE_DRAKE]                    = %s,\n' % val, s); assert n == 1, p; wr(p, s)

p = 'src/data/object_events/object_event_graphics.h'; s = rd(p)
if 'OrangeDrake' not in s:
    s = sub1(s, 'const u16 gObjectEventPalette_Luana[] = INCBIN_U16("graphics/object_events/pics/people/luana.gbapal");\n',
        'const u16 gObjectEventPalette_Luana[] = INCBIN_U16("graphics/object_events/pics/people/luana.gbapal");\n'
        'const u16 gObjectEventPic_OrangeDrake[] = INCBIN_U16("graphics/object_events/pics/people/orange_drake.4bpp");\n'
        'const u16 gObjectEventPalette_OrangeDrake[] = INCBIN_U16("graphics/object_events/pics/people/orange_drake.gbapal");\n', p); wr(p, s)
p = 'src/data/object_events/object_event_pic_tables.h'; s = rd(p)
if 'sPicTable_OrangeDrake' not in s:
    s = sub1(s, '    overworld_frame(gObjectEventPic_Luana, 2, 4, 9),\n};\n', '    overworld_frame(gObjectEventPic_Luana, 2, 4, 9),\n};\n\nstatic const struct SpriteFrameImage sPicTable_OrangeDrake[] = {\n'
        + ''.join('    overworld_frame(gObjectEventPic_OrangeDrake, 2, 4, %d),\n' % i for i in range(10)) + '};\n', p); wr(p, s)
p = 'src/data/object_events/object_event_graphics_info.h'; s = rd(p)
if 'gObjectEventGraphicsInfo_OrangeDrake' not in s:
    i = s.index('const struct ObjectEventGraphicsInfo gObjectEventGraphicsInfo_Luana = {'); j = s.index('};\n', i) + 3
    blk = s[i:j].replace('Luana', 'OrangeDrake').replace('OBJ_EVENT_PAL_LUANA', 'OBJ_EVENT_PAL_ORANGE_DRAKE')
    s = s[:j] + '\n// Drake, head of the Orange League (graphics/object_events/pics/people/orange_drake.png)\n' + blk + s[j:]; wr(p, s)
p = 'src/data/object_events/object_event_graphics_info_pointers.h'; s = rd(p)
if 'OrangeDrake' not in s:
    s = sub1(s, 'const struct ObjectEventGraphicsInfo gObjectEventGraphicsInfo_Luana;\n', 'const struct ObjectEventGraphicsInfo gObjectEventGraphicsInfo_Luana;\nconst struct ObjectEventGraphicsInfo gObjectEventGraphicsInfo_OrangeDrake;\n', p)
    s, n = re.subn(r'(    \[OBJ_EVENT_GFX_LUANA\]\s*= &gObjectEventGraphicsInfo_Luana,\n)', r'\1    [OBJ_EVENT_GFX_ORANGE_DRAKE]             = &gObjectEventGraphicsInfo_OrangeDrake,\n', s); assert n == 1
    wr(p, s)
p = 'src/event_object_movement.c'; s = rd(p)
if 'OBJ_EVENT_PAL_ORANGE_DRAKE' not in s:
    s, n = re.subn(r'(#define OBJ_EVENT_PAL_LUANA\s+0x1129\n)', r'\1#define OBJ_EVENT_PAL_ORANGE_DRAKE                  0x112A\n', s); assert n == 1
    s, n = re.subn(r'(    \{gObjectEventPalette_Luana,\s+OBJ_EVENT_PAL_LUANA\},\n)', r'\1    {gObjectEventPalette_OrangeDrake,       OBJ_EVENT_PAL_ORANGE_DRAKE},\n', s); assert n == 1
    wr(p, s)
p = 'src/data/trainers.h'; s = rd(p)
i = s.index('[TRAINER_CHAMPION_DRAKE] = {'); j = s.index('.trainerPic = ', i); k = s.index(',', j)
s = s[:j] + '.trainerPic = TRAINER_PIC_ORANGE_DRAKE' + s[k:]; wr(p, s)
import os
p = 'spritesheet_rules.mk'; s = rd(p)
if 'people/cissy.4bpp' not in s:
    anchor = '$(OBJEVENTGFXDIR)/people/elm.4bpp: %.4bpp: %.png\n\t$(GFX) $< $@ -mwidth 2 -mheight 4\n'
    s = sub1(s, anchor, anchor + ''.join('\n$(OBJEVENTGFXDIR)/people/%s.4bpp: %%.4bpp: %%.png\n\t$(GFX) $< $@ -mwidth 2 -mheight 4\n' % k
        for k in ['ivy', 'cissy', 'danny', 'rudy', 'luana', 'orange_drake']), p); wr(p, s)
for k in ['ivy', 'cissy', 'danny', 'rudy', 'luana', 'orange_drake']:
    f = 'graphics/object_events/pics/people/%s.4bpp' % k
    if os.path.exists(f): os.remove(f)
p = 'src/event_object_movement.c'; s = rd(p)
if 'IsCustomNpcPaletteTag' not in s:
    s = sub1(s, '''static bool8 IsDynamicObjectEventPaletteTag(u16 paletteTag)
{
    return (paletteTag >= FOLLOWER_PAL_TAG_BASE && paletteTag < FOLLOWER_PAL_TAG_BASE + FOLLOWER_GFX_COUNT)
        || IsShinyFollowerPaletteTag(paletteTag);
}''', '''// The added NPCs (Johto and Orange League characters) have their own palettes in
// sObjectEventSpritePalettes. They are loaded on demand too, like follower palettes, so any
// number of them can share a map with the regular NPCs.
static bool8 IsCustomNpcPaletteTag(u16 paletteTag)
{
    return paletteTag >= OBJ_EVENT_PAL_WALKER && paletteTag <= OBJ_EVENT_PAL_ORANGE_DRAKE;
}

static bool8 IsDynamicObjectEventPaletteTag(u16 paletteTag)
{
    return (paletteTag >= FOLLOWER_PAL_TAG_BASE && paletteTag < FOLLOWER_PAL_TAG_BASE + FOLLOWER_GFX_COUNT)
        || IsShinyFollowerPaletteTag(paletteTag)
        || IsCustomNpcPaletteTag(paletteTag);
}''', p)
    s = sub1(s, '''    if (IsShinyFollowerPaletteTag(paletteTag))
    {
        u16 species = paletteTag - FOLLOWER_SHINY_PAL_TAG_BASE;''', '''    if (IsCustomNpcPaletteTag(paletteTag))
    {
        u8 index = FindObjectEventPaletteIndexByTag(paletteTag);
        if (index == 0xFF)
            return 0xFF;
        spritePalette.data = sObjectEventSpritePalettes[index].data;
    }
    else if (IsShinyFollowerPaletteTag(paletteTag))
    {
        u16 species = paletteTag - FOLLOWER_SHINY_PAL_TAG_BASE;''', p)
    wr(p, s)
p = 'src/data/object_events/object_event_graphics_info.h'; s = rd(p)
for t in 'WALKER BUGSY WHITNEY MORTY CHUCK JASMINE PRYCE CLAIR ELM IVY CISSY DANNY RUDY LUANA ORANGE_DRAKE'.split():
    s, n = re.subn(r'(\.paletteTag = OBJ_EVENT_PAL_%s,\n(?:.*\n){4}?\s*\.paletteSlot = )[^,]+,' % t, r'\1PALSLOT_DYNAMIC,', s); assert n == 1, t
wr(p, s)
print('orange overworld + drake art ok')
